# Seeded rather than hardcoded so the prompts can be retuned without a deploy.
# Changing a row's prompt invalidates that stage's cached extractions.
DEFAULT_LLM_MODEL = "gpt-4.1"
DEFAULT_PROMPTS = {
    "context": prompts.CONTEXT_SYSTEM,
    "unit": prompts.UNIT_SYSTEM,
    "unit_merge": prompts.UNIT_MERGE_SYSTEM,
}


def add_course_profile_configurations(apps, schema_editor):
    """Seed one configuration per stage"""
    Configuration = apps.get_model("learning_resources", "CourseProfileConfiguration")
    for stage, prompt in DEFAULT_PROMPTS.items():
        Configuration.objects.get_or_create(
            stage=stage, defaults={"llm_model": DEFAULT_LLM_MODEL, "prompt": prompt}
        )


